function parseIds(val) {
  if (val === null || val === undefined || val === '') return [];
  if (Array.isArray(val)) return val.map(Number).filter(n => !isNaN(n));
  let s = String(val).trim();
  if (s.startsWith('[') && s.endsWith(']')) {
    try {
      const arr = JSON.parse(s);
      return (Array.isArray(arr) ? arr : [arr]).map(Number).filter(n => !isNaN(n));
    } catch(e) {}
  }
  return s.split(',').map(x => x.trim()).filter(Boolean).map(Number).filter(n => !isNaN(n));
}

function nomiDaIds(val) {
  return parseIds(val).map(id => {
    const p = persone.find(x => x.id === id);
    return p ? p.nome_cognome : null;
  }).filter(Boolean);
}

const result = pratiche.map(p => {
  const prop = proprieta.find(x => x.id === p.proprieta_id);
  const venditoriNomi = nomiDaIds(p.venditori_ids);
  const acquirentiNomi = nomiDaIds(p.acquirenti_ids);
